// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    StaxLPStaking c;
    function setUp() public { c = new StaxLPStaking(address(this), address(this)); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(this));
        vm.assume(newOwner != address(0));
        vm.assume(caller != c.owner());

        address ownerBefore = c.owner();
        vm.prank(caller);
        bool ok = false;
        try c.transferOwnership(newOwner) { ok = true; } catch { ok = false; }
        assertTrue(!ok && c.owner() == ownerBefore);
    }
}
